struct RigSpec {
    bones:&'static [GeneratedBone],
    cubes:&'static [GeneratedCube],
    chains:&'static [&'static [usize]],
    keys:&'static [GeneratedKey],
    idle:&'static str,
    walk:&'static str,
    walk_duration:f32,
    texture:&'static str,
    model_scale:f32,
}
