/// Approximate authored silhouette dimensions (in blocks), including
/// the native renderer's scale. A zombie template's vanilla hitbox is not
/// the visual size of the original RustPG mesh.
pub fn preview_dimensions(kind:&str)->Option<[f32;2]> {
    let spec=rig(kind)?;
    if spec.cubes.is_empty(){return None;}
    let (mut min_x,mut min_y,mut min_z)=(f32::INFINITY,f32::INFINITY,f32::INFINITY);
    let (mut max_x,mut max_y,mut max_z)=(f32::NEG_INFINITY,f32::NEG_INFINITY,f32::NEG_INFINITY);
    for cube in spec.cubes {
        min_x=min_x.min(cube.from[0]); max_x=max_x.max(cube.to[0]);
        min_y=min_y.min(cube.from[1]); max_y=max_y.max(cube.to[1]);
        min_z=min_z.min(cube.from[2]); max_z=max_z.max(cube.to[2]);
    }
    // Diagonal horizontal clearance keeps a rotating creature inside its clip.
    let width=(((max_x-min_x).powi(2)+(max_z-min_z).powi(2)).sqrt()
        /16.0*spec.model_scale).max(0.5);
    let height=((max_y-min_y)/16.0*spec.model_scale).max(0.5);
    (width.is_finite()&&height.is_finite()).then_some([width,height])
}

fn sample_channel(keys:&[GeneratedKey],clip:&str,bone:&str,channel:&str,
    time:f32,default:[f32;3])->[f32;3] {
    let mut left=None;let mut right=None;
    for key in keys {
        if key.clip!=clip||key.bone!=bone||key.channel!=channel{continue;}
        if key.time<=time&&left.is_none_or(|prev:&GeneratedKey|key.time>prev.time){left=Some(key);}
        if key.time>=time&&right.is_none_or(|prev:&GeneratedKey|key.time<prev.time){right=Some(key);}
    }
    match(left,right){
        (Some(a),Some(b)) if b.time>a.time=>{
            let f=((time-a.time)/(b.time-a.time)).clamp(0.0,1.0);
            std::array::from_fn(|i|a.value[i]+(b.value[i]-a.value[i])*f)
        },
        (Some(a),_)=>a.value,
        (_,Some(b))=>b.value,
        _=>default,
    }
}
fn part_tint(kind:&str,name:&str)->u32{
    match kind {
        MANA_HOUND=>if name.contains("mana_spine"){0x61E8FF}else if name.contains("fang"){0xE6FBFF}else{0xD6EAF2},
        GRAVE_KNIGHT=>if name.contains("visor")||name.contains("horn"){0xBC83FF}else if name.contains("blade"){0xD9E1E8}else{0xA8A8B8},
        RIFT_MANTIS=>if name.contains("blade"){0xFF6AF2}else if name.contains("crest"){0x73F5E0}else{0xB8B7D8},
        CRYSTAL_WYRM=>if name.contains("crystal")||name.contains("horn"){0x70E8FF}else if name.contains("fang"){0xE8FFFF}else{0xB7DCE5},
        ECLIPSE_OGRE=>if name.contains("core"){0xFF5C3D}else if name.contains("horn")||name.contains("club_head"){0xFFC15C}else{0xC4A49A},
        SENTINEL=>if name=="core_crystal"{0xFFD08B}else if name=="faceplate"{0xFFB56A}else if name.contains("horn"){0xCB92E8}else{0xFFFFFF},
        HUNTER=>if name.contains("fang"){0xC6FAF1}else if name.contains("talon"){0xA0D9DE}else if name=="muzzle"{0xB9F1E7}else{0xFFFFFF},
        DUSK_REVENANT=>if name.contains("visor") || name.contains("core") {0xC9A5FF}else{0xC8B5E8},
        STORM_GRYPHON=>if name.contains("feather") {0x86D7FF}else if name.contains("beak") {0xFFE0A1}else{0xD2E4F8},
        RUNE_COLOSSUS=>if name.contains("rune")||name.contains("heart")||name.contains("sigil") {0x74FFD2}else{0xCDD7CF},
        EMBER_IMP=>if name.contains("wing")||name.contains("fire") {0xFFAB54}else{0xF6C6A3},
        ABYSS_WEAVER=>if name.contains("spine")||name.contains("eye") {0xCD78FF}else{0xB0A0D8},
        _=>0xFFFFFF,
    }
}

struct NativeRig{kind:&'static str}
impl EntityRenderer for NativeRig{
    fn submit(&self,entity:&EntityRenderState,
        draw:&mut dyn BlockEntityDrawContext)->Result<(),String>{
        let Some(living)=entity.living.as_ref()else{return Ok(())};
        let Some(spec)=rig(self.kind)else{return Ok(())};
        if spec.cubes.len()!=spec.chains.len(){return Err("Corrupt creature cube ancestry".into());}
        let scaled=living.scale*living.age_scale;
        if !scaled.is_finite()||scaled<=0.0{return Ok(());}
        let idle_time=(entity.age/20.0).rem_euclid(2.0);
        let walk_time=(living.walk_animation_pos*0.16).rem_euclid(spec.walk_duration.max(0.01));
        let walking=living.walk_animation_speed.clamp(0.0,1.0);
        let ground=spec.cubes.iter().map(|c|c.from[1]).fold(f32::INFINITY,f32::min);
        draw.push();
        draw.rotate_about([0.0,1.0,0.0],-living.body_rot,[0.0;3]);
        draw.scale([scaled*spec.model_scale;3]);
        if ground.is_finite(){draw.translate([0.0,-ground/16.0,0.0]);}
        for(part,path)in spec.cubes.iter().zip(spec.chains.iter()){
            draw.push();
            for &index in path.iter(){
                let Some(bone)=spec.bones.get(index)else{return Err("Corrupt creature bone index".into())};
                let idle=sample_channel(spec.keys,spec.idle,bone.name,"rotation",idle_time,[0.0;3]);
                let moving=sample_channel(spec.keys,spec.walk,bone.name,"rotation",walk_time,[0.0;3]);
                let mut rotation:[f32;3]=std::array::from_fn(|axis|
                    bone.rotation[axis]+idle[axis]+moving[axis]*walking);
                if bone.name=="head"{
                    rotation[0]+=living.x_rot*0.25;
                    rotation[1]+=living.y_rot*0.35;
                }
                let pivot=bone.pivot.map(|v|v/16.0);
                for(axis,degrees)in[
                    ([0.0,0.0,1.0],rotation[2]),
                    ([0.0,1.0,0.0],rotation[1]),
                    ([1.0,0.0,0.0],rotation[0])
                ]{
                    if degrees.abs()>0.0001{draw.rotate_about(axis,degrees,pivot);}
                }
                let size=sample_channel(spec.keys,spec.idle,bone.name,"scale",idle_time,[1.0;3]);
                if size.iter().any(|v|(v-1.0).abs()>0.0001){
                    draw.translate(pivot);draw.scale(size);draw.translate(pivot.map(|v|-v));
                }
            }
            let pivot=part.origin.map(|v|v/16.0);
            for(axis,degrees)in[
                ([0.0,0.0,1.0],part.rotation[2]),
                ([0.0,1.0,0.0],part.rotation[1]),
                ([1.0,0.0,0.0],part.rotation[0])
            ]{
                if degrees.abs()>0.0001{draw.rotate_about(axis,degrees,pivot);}
            }
            let face=Some(CubeFace::new(spec.texture));
            let _=draw.cube(part.from,part.to,[face;6],part_tint(self.kind,part.name));
            draw.pop();
        }
        draw.pop();Ok(())
    }
}

#[derive(Default)]struct LeapingAttack{left:u32}
impl Goal for LeapingAttack{
    fn flags(&self)->GoalFlags{GoalFlags::JUMP.union(GoalFlags::LOOK)}
    fn can_use(&mut self,cx:&mut GoalContext<'_>)->bool{
        cx.random().next_int_bound(90).unwrap_or(1)==0
    }
    fn can_continue(&mut self,_:&mut GoalContext<'_>)->bool{self.left>0}
    fn start(&mut self,_:&mut GoalContext<'_>){self.left=12;}
    fn tick(&mut self,cx:&mut GoalContext<'_>){
        if self.left==7{cx.jump();}
        self.left=self.left.saturating_sub(1);
    }
    fn name(&self)->&'static str{"rustpg:telegraphed_leap"}
}
pub struct PouncerGoals;
#[mod_api::horizon_part]
impl EntityPart for PouncerGoals{
    fn register_goals(&self,goals:&mut GoalRegistrar<'_>){
        goals.add_goal(3,LeapingAttack::default());
    }
}

pub fn register_entities(registrar:&mut dyn mod_api::Registrar){
    for kind in [HUNTER,MANA_HOUND,RIFT_MANTIS,STORM_GRYPHON,EMBER_IMP]{
        registrar.entity_part(kind,PouncerGoals);
    }
}
pub fn register_renderers(event:&mut mod_api::RegisterEntityRenderersEvent<'_>){
    for &kind in CREATURES{
        event.renderers.register(kind.into(),Arc::new(NativeRig{kind}));
    }
}
#[cfg(test)]mod tests{
    use super::*;
    #[test]fn every_original_creature_has_a_finite_preview_fit(){
        for &kind in CREATURES {
            let [w,h]=preview_dimensions(kind).expect(kind);
            assert!(w>0.0 && h>0.0 && w.is_finite() && h.is_finite(),"{kind}");
        }
        assert_eq!(preview_dimensions("minecraft:zombie"),None);
    }
    #[test]fn roster_has_real_bones_and_cubes(){
        for &kind in CREATURES{
            let r=rig(kind).unwrap();
            assert!(r.bones.len()>=13,"{kind}");
            assert!(r.cubes.len()>=19,"{kind}");
            assert_eq!(r.cubes.len(),r.chains.len());
            for c in r.chains{
                assert!(!c.is_empty());
                assert!(c.iter().all(|i|*i<r.bones.len()));
            }
        }
    }
    #[test]fn new_roster_has_motion_keys(){
        for kind in [MANA_HOUND,GRAVE_KNIGHT,RIFT_MANTIS,CRYSTAL_WYRM,ECLIPSE_OGRE,
            DUSK_REVENANT,STORM_GRYPHON,RUNE_COLOSSUS,EMBER_IMP,ABYSS_WEAVER]{
            let r=rig(kind).unwrap();
            assert!(r.keys.iter().any(|k|k.clip==r.idle));
            assert!(r.keys.iter().any(|k|k.clip==r.walk));
        }
    }
}
